// Java equivalent: start every call on a virtual thread, then join them all
static Map<String, Integer> weighAll(List<String> items, Function<String, Integer> weigh) {
    try (var vthreads = Executors.newVirtualThreadPerTaskExecutor()) {
        Map<String, CompletableFuture<Integer>> pending = new LinkedHashMap<>();
        for (String item : items) {
            pending.put(item, CompletableFuture.supplyAsync(() -> weigh.apply(item), vthreads));   // start all
        }
        Map<String, Integer> result = new LinkedHashMap<>();
        pending.forEach((item, f) -> result.put(item, f.join()));                               // then wait
        return result;
    }
}

